"""T131: synthetic water/fictional channel ledger, no research or remote access."""
from concurrent.futures import ProcessPoolExecutor
from hashlib import sha256
import json
import multiprocessing
import os
from pathlib import Path

import pytest

from ag import catalog, catalog_v2 as v2, cli
from test_catalog import QUOTE, files, make_attempt, obj, water, write_json

XYZ = b'3\nSynthetic water\nO 0 0 0\nH 0 0 1\nH 0 1 0\n'
GEOMETRY = 'O 0 0 0\nH 0 0 1\nH 0 1 0'
# Generated by unmodified main 1e1d66b (catalog matches v4.5.1), frozen UTC clock.
V1_JOURNAL = b'{"at":"2026-01-01T00:00:00+00:00","conformer":null,"id":"water-a","multiplicity":1,"name":"Water","note":null,"op":"object","prev_sha256":null,"schema":"ag-catalog/1","seq":1,"state_label":null,"update":false}\n{"at":"2026-01-01T00:00:00+00:00","conformer":null,"id":"water-b","multiplicity":null,"name":"Other","note":null,"op":"object","prev_sha256":"af7ae93da5a35bf7df59cbb25504096a23b09e4dfdbdea7c351b85156330a5b1","schema":"ag-catalog/1","seq":2,"state_label":null,"update":false}\n'
V1_STATE_HASH = '5f5c02c9ab22b5a563ca0eef5a9ece53516e861314a1fec53788145674db11e7'
V1_UPDATED_JOURNAL_HASH = 'df91057cbeef6e981200538cd90a9619744d4f4005fafc3eb31d6b2b2fc443de'
V1_UPDATED_STATE_HASH = '0ebeae8c3eba087c94c91f841d7382dc142f2f799d13f71daddb1d7b4b5fbba7'


def channel(root, identity='a', **fields):
    return catalog.change(root, 'channel', object='water-a', id=identity, name=identity,
                          definition='Fictional approach label; no chemistry inferred', **fields)


def candidate(root, identity='guess-a', **fields):
    source = root / 'water.xyz'
    if 'xyz' not in fields and not source.exists():
        source.write_bytes(XYZ)
    return catalog.change(root, 'candidate', object='water-a', id=identity,
                          xyz=fields.pop('xyz', source), origin=fields.pop('origin', 'manual'), **fields)


def result(root, **fields):
    return catalog.change(root, 'candidate-result', object='water-a', candidate='guess-a',
                          outcome=fields.pop('outcome', 'diagnosed'), **fields)


def state(root):
    return catalog.show(root)[0]['objects'][0]


def setup(root):
    obj(root)
    channel(root, upgrade_catalog=True)
    channel(root, 'b', discovered=True)


def facts_imag(root, identity, value):
    path = root / 'attempts' / identity / 'facts.json'
    facts = json.loads(path.read_text())
    facts['n_imag'] = value
    write_json(path, facts)


def tree(root):
    return {str(p.relative_to(root)): (p.is_dir(), p.stat().st_mode,
            p.read_bytes() if p.is_file() else None) for p in root.rglob('*')}


def test_main_v1_bytes_and_old_event_after_upgrade(water, monkeypatch):
    monkeypatch.setattr(catalog, 'now', lambda: '2026-01-01T00:00:00+00:00')
    (water / 'catalog').mkdir()
    (water / 'catalog/journal.jsonl').write_bytes(V1_JOURNAL)
    raw, events, _ = catalog.read_journal(water)
    encoded = catalog.encode(catalog.derived_state(water, events, raw))
    assert sha256(encoded).hexdigest() == V1_STATE_HASH
    catalog.change(water, 'object', id='water-a', name='Renamed', update=True)
    assert sha256((water / 'catalog/state.json').read_bytes()).hexdigest() == V1_UPDATED_STATE_HASH
    assert sha256((water / 'catalog/journal.jsonl').read_bytes()).hexdigest() == V1_UPDATED_JOURNAL_HASH
    prefix = (water / 'catalog/journal.jsonl').read_bytes()
    channel(water, upgrade_catalog=True)
    catalog.change(water, 'object', id='water-a', name='Again', update=True)
    raw, events, _ = catalog.read_journal(water)
    assert raw.startswith(prefix)
    assert [e['schema'] for e in events] == ['ag-catalog/1'] * 3 + ['ag-catalog/2'] * 2
    assert catalog.show(water)[0]['schema'] == 'ag-catalog-state/2'
    assert state(water)['channels'][0]['status'] == 'untried'


@pytest.mark.parametrize('existing', [False, True])
def test_upgrade_refusal_and_preview_leave_every_file_unchanged(water, existing):
    if existing:
        obj(water)
    before = tree(water)
    fields = dict(formula='OH2', charge='0', update=existing)
    with pytest.raises(ValueError, match='--upgrade-catalog'):
        obj(water, **fields)
    assert tree(water) == before
    preview = obj(water, dry_run=True, **fields)
    assert preview['checks']['catalog_upgrade'] and 'v4.5.x' in preview['warnings'][0]
    assert preview['events'][0]['expected_formula'] == dict(state='set', value='H2O')
    assert tree(water) == before
    obj(water, upgrade_catalog=True, **fields)
    assert state(water)['expected']['charge'] == dict(state='set', value=0)


@pytest.mark.parametrize('damage', ['downgrade', 'v1-op', 'v1-field', 'unknown-field', 'new-op', 'checks', 'partial'])
def test_schema_and_v2_damage_refused_without_repair(water, damage):
    setup(water)
    path = water / 'catalog/journal.jsonl'
    events = [json.loads(line) for line in path.read_bytes().splitlines()]
    if damage == 'downgrade':
        events[-1]['schema'] = 'ag-catalog/1'
    elif damage == 'v1-op':
        events[0]['op'] = 'channel'
    elif damage == 'v1-field':
        events[0]['expected_charge'] = dict(state='set', value=0)
    elif damage == 'unknown-field':
        events[0]['new_field'] = True
    elif damage == 'new-op':
        events[-1]['op'] = 'repair'
    elif damage == 'checks':
        events[-1]['confirmed'] = 'yes'
    data, previous = b'', None
    for event in events:
        event['prev_sha256'] = previous
        line = catalog.encode(event)
        data += line
        previous = sha256(line).hexdigest()
    path.write_bytes(data[:-1] if damage == 'partial' else data)
    before = tree(water)
    for action in (lambda: catalog.show(water), lambda: catalog.suggest(water), lambda: channel(water, 'c')):
        with pytest.raises(ValueError, match='journal damaged'):
            action()
    assert tree(water) == before


def test_expected_tristate_preservation_and_formula(water):
    obj(water, formula='OH2', charge='0', upgrade_catalog=True)
    obj(water, update=True, note='Legacy update omits expectation fields')
    assert state(water)['expected'] == dict(formula=dict(state='set', value='H2O'), charge=dict(state='set', value=0))
    assert 'expected_charge' not in catalog.read_journal(water)[1][-1]
    obj(water, update=True, charge='unknown', formula='unknown')
    assert state(water)['expected']['charge'] == dict(state='unknown', value=None)
    obj(water, update=True, charge='unset', formula='unset')
    assert state(water)['expected']['formula'] == dict(state='unset', value=None)
    assert v2.formula('H10C4') == 'C4H10'
    assert v2.formula('OHHO') == 'H2O2'
    assert v2.formula('NaCl') == 'ClNa'
    for bad in ('X2', 'H0', 'H02', 'H2O+', '(OH)2', 'H-2', 'C1.5H3', ''):
        with pytest.raises(ValueError):
            v2.formula(bad)


@pytest.mark.parametrize('kind', ['single', 'qst', 'qst-bad', 'xtb', 'crest', 'xtb-missing', 'xtb-hash', 'missing'])
def test_object_suggest_provenance_and_missing_values(water, kind, capsys):
    science = dict(geometry=GEOMETRY, charge=0, multiplicity=1)
    template = kind if kind in ('xtb', 'crest') else 'xtb' if kind.startswith('xtb-') else 'gaussian'
    if kind.startswith('qst'):
        science = dict(qst_mode='QST2', structures=[science.copy(), science.copy()])
        if kind == 'qst-bad':
            science['structures'][1].update(geometry='He 0 0 0', charge=1, multiplicity=2)
    if kind == 'missing':
        science = {}
    identity = make_attempt(water, '001-input', template=template, **science)
    path = water / 'attempts' / identity
    if template in ('xtb', 'crest'):
        (path / 'inputs').mkdir()
        (path / 'inputs/input.xyz').write_bytes(XYZ)
        manifest = json.loads((path / 'manifest.json').read_text())
        manifest['inputs'] = [dict(name='input.xyz', size=len(XYZ), sha256=sha256(XYZ).hexdigest())]
        manifest['template_params'] = {'--chrg': '0', '--uhf': '0'}
        if kind == 'xtb-missing':
            manifest['template_params'] = {}
            manifest['science'] = {}
        if kind == 'xtb-hash':
            manifest['inputs'][0]['sha256'] = '0' * 64
        write_json(path / 'manifest.json', manifest)
    before = files(water)
    suggestion = v2.object_suggest(water, identity)
    if kind in ('single', 'qst', 'xtb', 'crest'):
        assert suggestion['suggested'] == dict(formula='H2O', charge=0, multiplicity=1)
        assert '--charge 0' in suggestion['command']
    elif kind in ('qst-bad', 'missing'):
        assert not suggestion['suggested'] and set(suggestion['unavailable']) == {'formula', 'charge', 'multiplicity'}
    elif kind == 'xtb-missing':
        assert suggestion['suggested'] == dict(formula='H2O')
    else:
        assert 'formula' in suggestion['unavailable']
    assert cli.main(['catalog', 'object-suggest', str(water), '--attempt', identity]) == 0
    output = capsys.readouterr().out
    assert '无法建议' in output if suggestion['unavailable'] else '--charge 0' in output
    assert files(water) == before and not (water / 'catalog').exists()


def test_member_mismatches_and_unknown_are_reports_only(water):
    identity = make_attempt(water, '001-water', geometry=GEOMETRY, charge=0, multiplicity=1)
    evidence = files(water)
    obj(water, formula='H2O', charge='0', multiplicity=1, upgrade_catalog=True)
    catalog.change(water, 'member', object='water-a', attempt=identity, role='auto')
    old = (water / 'catalog/journal.jsonl').read_bytes()
    obj(water, update=True, formula='CH4', charge='-1', multiplicity=3)
    mismatches = state(water)['member_mismatches']
    assert {m['field'] for m in mismatches} == {'formula', 'charge', 'multiplicity'}
    assert catalog.suggest(water)['expectation_reports'][0]['member_mismatches'] == mismatches
    assert any('mismatch' in w for w in catalog.show(water)[1])
    obj(water, update=True, formula='unknown', charge='unset')
    assert [m['field'] for m in state(water)['member_mismatches']] == ['multiplicity']
    assert any('unknown' in w and '跳过' in w for w in catalog.show(water)[1])
    assert (water / 'catalog/journal.jsonl').read_bytes().startswith(old)
    assert {k: files(water)[k] for k in evidence} == evidence


def test_channel_priority_confirmation_declarations_and_coverage(water):
    setup(water)
    assert [c['status'] for c in state(water)['channels']] == ['untried', 'pending_confirmation']
    with pytest.raises(ValueError, match='already exists'):
        channel(water)
    candidate(water, target_channel='a')
    assert state(water)['channels'][0]['status'] == 'attempted_not_found'
    result(water, assign='tentative', channel=['a'])
    result(water, assign='tentative', channel=['b'])
    assert [c['status'] for c in state(water)['channels']] == ['tentative_found', 'pending_confirmation']
    channel(water, 'b', update=True, confirm=True)
    assert state(water)['channels'][1]['status'] == 'tentative_found'
    declaration = dict(object='water-a', channel='b', status='verified', quote=QUOTE)
    with pytest.raises(ValueError, match='verified candidate'):
        catalog.change(water, 'channel-status', **declaration)
    identity = make_attempt(water, '001-ts', '# HF/STO-3G Opt=TS Freq')
    facts_imag(water, identity, 1)
    catalog.change(water, 'member', object='water-a', attempt=identity, role='auto')
    result(water, outcome='accepted', assign='verified', channel=['b'], attempt=identity, quote=QUOTE)
    # Verified assignment alone does not declare a verified channel.
    assert state(water)['channels'][1]['status'] == 'tentative_found'
    catalog.change(water, 'channel-status', **declaration)
    assert state(water)['channels'][1]['status'] == 'verified'
    for fields in (dict(quote=QUOTE), dict(reason='Limited template', quote='')):
        with pytest.raises(ValueError):
            catalog.change(water, 'channel-status', object='water-a', channel='b',
                           status='excluded-low-confidence', **fields)
    catalog.change(water, 'channel-status', object='water-a', channel='b',
                   status='excluded-low-confidence', reason='Limited template', quote=QUOTE)
    assert state(water)['channels'][1]['status'] == 'excluded_low_confidence'
    catalog.change(water, 'channel-status', object='water-a', channel='b', status='cleared', quote=QUOTE)
    assert state(water)['channels'][1]['status'] == 'tentative_found'
    for statement in ('stable', 'withdrawn'):
        catalog.change(water, 'coverage', object='water-a', statement=statement,
                       scope='Fictional a,b only', budget='Three synthetic guesses', quote=QUOTE)
        assert state(water)['coverage']['statement'] == statement
        assert state(water)['coverage']['quote'] == QUOTE
    catalog.change(water, 'retire', object='water-a', reason='Historical fixture')
    with pytest.raises(ValueError, match='retired'):
        channel(water, 'c')


@pytest.mark.parametrize('data', [b'', b'0\nempty\n', b'2\nshort\nH 0 0 0\n',
    b'1\nx\nXx 0 0 0\n', b'1\nx\nH nan 0 0\n', b'1\nx\nH 1e999 0 0\n',
    XYZ + XYZ, b' ' * (1024 * 1024 + 1)],
    ids=['empty', 'zero', 'truncated', 'element', 'nan', 'infinite', 'two-frames', 'oversize'])
def test_bad_xyz_does_not_archive_or_append(water, data):
    setup(water)
    source = water / 'bad.xyz'
    source.write_bytes(data)
    before = tree(water)
    with pytest.raises(ValueError):
        candidate(water, xyz=source)
    assert tree(water) == before


def test_archive_reuse_symlinks_and_provenance(water):
    setup(water)
    obj(water, update=True, formula='CH4', charge='0')
    parent = make_attempt(water, '001-parent')
    transform = water / 'transform.json'
    transform.write_text('{"unknown_operation":{"atoms":[1,2],"amount":0}}')
    source = water / 'water.xyz'
    source.write_bytes(XYZ)
    first = candidate(water, parent_attempt=parent, parent_file=source, transform_json=transform, target_channel='a')
    assert first['checks']['expected_formula']['matches'] is False and first['warnings']
    assert first['checks']['expected_charge']['checked'] is False
    record = first['events'][0]
    archive = water / record['file']
    saved = files(water)
    candidate(water, 'guess-b', origin='literature', doi='10.1234/synthetic', si_location='Synthetic example')
    assert len(list(archive.parent.iterdir())) == 1
    assert (archive.read_bytes(), archive.stat().st_mtime_ns) == saved[record['file']]
    assert archive.stat().st_mode & 0o777 == 0o400
    assert archive.parent.stat().st_mode & 0o777 == 0o700
    assert record['parent']['file']['sha256'] == sha256(XYZ).hexdigest()
    assert record['transform'] == json.loads(transform.read_text())
    for fields in (dict(origin='literature'), dict(parent_attempt='missing'), dict(target_channel='missing')):
        with pytest.raises(ValueError):
            candidate(water, 'guess-c', **fields)
    link = water / 'link.xyz'
    link.symlink_to(source)
    with pytest.raises(ValueError, match='Symbolic links'):
        candidate(water, 'guess-c', xyz=link)
    archive.rename(archive.with_suffix('.saved'))
    archive.symlink_to(source)
    with pytest.raises(ValueError, match='Symbolic links'):
        candidate(water, 'guess-c')


@pytest.mark.parametrize('fields', [dict(assign='tentative', channel=['a','b']),
    dict(assign='none', channel=['a']), dict(assign='undetermined', channel=['a']),
    dict(assign='tentative'), dict(assign='undetermined', channel=['a','a']),
    dict(assign='verified', channel=['a']), dict(outcome='other')])
def test_invalid_result_assignment(water, fields):
    setup(water)
    candidate(water)
    before = files(water)
    with pytest.raises(ValueError):
        result(water, **fields)
    assert files(water) == before


@pytest.mark.parametrize('failure', ['unfetched', 'unreadable', 'zero', 'many', 'missing', 'boolean', 'nonmember', 'noquote'])
def test_verified_checks_are_bound_and_never_auto_add_member(water, failure):
    setup(water)
    candidate(water)
    identity = make_attempt(water, '001-ts', status='prepared' if failure == 'unfetched' else 'fetched')
    facts_imag(water, identity, {'zero':0, 'many':2, 'missing':None, 'boolean':True}.get(failure, 1))
    if failure == 'unreadable':
        (water / 'attempts' / identity / 'facts.json').write_text('[]')
    if failure != 'nonmember':
        catalog.change(water, 'member', object='water-a', attempt=identity, role='auto')
    before = files(water)
    with pytest.raises(ValueError):
        result(water, assign='verified', channel=['a'], attempt=identity, quote=None if failure == 'noquote' else QUOTE)
    assert files(water) == before


def test_all_result_history_undetermined_ledger_and_cli(water, capsys):
    setup(water)
    candidate(water, target_channel='a')
    identity = make_attempt(water, '001-ts')
    diagnosis = water / 'diagnosis.json'
    diagnosis.write_text('{"arbitrary":[0,false,null,"unknown"]}')
    first = result(water, diagnosis_json=diagnosis, attempt=identity, assign='undetermined', channel=['a','b'])
    assert first['warnings'] and not state(water)['members']
    result(water, outcome='opt_failed')
    result(water, outcome='minimum', assign='undetermined')
    candidate(water, 'no-target')
    value = state(water)
    assert value['channels'][0]['status'] == 'attempted_not_found'
    assert value['channels'][1]['status'] == 'pending_confirmation'
    channel(water, 'b', update=True, confirm=True)
    assert state(water)['channels'][1]['status'] == 'attempted_not_found'
    assert len(value['candidates'][0]['results']) == 3
    assert value['candidates'][0]['latest_assignment'] == dict(status='undetermined', channels=[])
    before = files(water)
    assert cli.main(['catalog','ledger',str(water),'--object','water-a','--json']) == 0
    ledger = json.loads(capsys.readouterr().out)
    assert len(ledger['channels']) == 2 and len(ledger['unassigned']) == 1
    assert [r['outcome'] for r in ledger['channels'][0]['candidates'][0]['results']] == ['diagnosed','opt_failed','minimum']
    assert cli.main(['catalog','ledger',str(water),'--object','water-a','--channel','a']) == 0
    assert 'True' in capsys.readouterr().out
    assert cli.main(['catalog','show',str(water)]) == 0
    output = capsys.readouterr().out
    assert 'LATEST ATTEMPT' in output and 'LATEST ASSIGNMENT' in output
    assert files(water) == before


def test_every_v2_write_dry_run_and_json_limits(water):
    setup(water)
    candidate(water)
    before = tree(water)
    proposals = [('object', dict(id='water-a', name='Water', update=True, formula='H2O')),
        ('channel', dict(object='water-a', id='c', name='C', definition='C')),
        ('channel-status', dict(object='water-a', channel='a', status='excluded-low-confidence', reason='Budget', quote=QUOTE)),
        ('coverage', dict(object='water-a', statement='stable', scope='a', budget='1', quote=QUOTE)),
        ('candidate', dict(object='water-a', id='new', xyz=water/'water.xyz', origin='scan')),
        ('candidate-result', dict(object='water-a', candidate='guess-a', outcome='diagnosed'))]
    for op, fields in proposals:
        catalog.change(water, op, dry_run=True, **fields)
        assert tree(water) == before
    path = water / 'invalid.json'
    for value in ('[]', '{"a":NaN}', '{"a":1e999}', '{"a":"' + 'x' * 65536 + '"}'):
        path.write_text(value)
        with pytest.raises(ValueError):
            result(water, diagnosis_json=path)
        with pytest.raises(ValueError):
            candidate(water, 'new', transform_json=path)


def concurrent_candidate(root, number):
    return catalog.change(Path(root), 'candidate', object='water-a', id=f'guess-{number}',
                          xyz=Path(root)/'water.xyz', origin='manual', upgrade_catalog=True)


def test_two_processes_share_lock_during_upgrade_and_archive(water):
    obj(water)
    (water/'water.xyz').write_bytes(XYZ)
    with ProcessPoolExecutor(max_workers=2, mp_context=multiprocessing.get_context('spawn')) as pool:
        list(pool.map(concurrent_candidate, [str(water)] * 6, range(6)))
    _, events, _ = catalog.read_journal(water)
    assert [e['seq'] for e in events] == list(range(1, 8))
    assert all(e['schema'] == 'ag-catalog/2' for e in events[1:])
    assert len(state(water)['candidates']) == 6
    assert len(list((water/'catalog/candidates').iterdir())) == 1


def test_first_candidate_dry_run_does_not_create_archive_directory_or_lock(water):
    obj(water)
    (water / 'water.xyz').write_bytes(XYZ)
    # No lock exists in an old imported journal; read-only preview must not create one.
    (water / 'catalog/catalog.lock').unlink()
    before = tree(water)
    preview = candidate(water, dry_run=True)
    assert preview['checks']['catalog_upgrade']
    assert tree(water) == before
    assert not (water / 'catalog/candidates').exists()


def test_candidate_directory_symlink_and_existing_corrupt_archive(water):
    setup(water)
    (water / 'water.xyz').write_bytes(XYZ)
    directory = water / 'catalog/candidates'
    directory.symlink_to(water / 'analyses', target_is_directory=True)
    with pytest.raises(ValueError, match='Symbolic links'):
        candidate(water)
    directory.unlink()
    directory.mkdir()
    target = directory / (sha256(XYZ).hexdigest() + '.xyz')
    target.write_bytes(b'corrupt')
    target.chmod(0o400)
    before = files(water)
    with pytest.raises(ValueError, match='archive hash mismatch'):
        candidate(water)
    assert files(water) == before


def test_archive_uses_validated_snapshot_even_if_source_changes(water, monkeypatch):
    setup(water)
    source = water / 'water.xyz'
    source.write_bytes(XYZ)
    save = v2.archive
    def changed_source(root, event, data, *, write=False):
        if write:
            source.write_bytes(b'1\nReplaced source\nHe 0 0 0\n')
        return save(root, event, data, write=write)
    monkeypatch.setattr(v2, 'archive', changed_source)
    event = candidate(water)['events'][0]
    assert (water / event['file']).read_bytes() == XYZ
    assert event['sha256'] == sha256(XYZ).hexdigest()
    assert source.read_bytes() != XYZ


@pytest.mark.parametrize('value', ['', ' \n ', 'x' * 2001], ids=['empty', 'blank', 'too-long'])
def test_conclusion_quotes_are_required_and_preserved(water, value):
    setup(water)
    before = files(water)
    for op, fields in [('channel-status', dict(channel='a', status='cleared')),
                       ('coverage', dict(statement='withdrawn', scope='a', budget='1'))]:
        with pytest.raises(ValueError, match='quote'):
            catalog.change(water, op, object='water-a', quote=value, **fields)
    assert files(water) == before
